// Grouped tool rows: a run of calls drawn as one summary row through Pi's
// real ToolExecutionComponent, collapsed and expanded, at 80 and 140 columns.
//
// The fixtures under tests/fixtures/mmr-tui-tool-groups/ are generated by
// this file: PI_MMR_UPDATE_FIXTURES=1 rewrites them, every other run pins
// them. Review the plain-text diff by eye before committing a refresh.

import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { after, describe, it, mock } from "node:test";
import { initTheme, ToolExecutionComponent } from "@earendil-works/pi-coding-agent";
import { getCapabilities, setCapabilities } from "@earendil-works/pi-tui";
import { cleanupLoadedSource, importSource } from "./helpers/load-src.mjs";
import { createMockPi } from "./helpers/pi-stub.mjs";

initTheme(undefined, false);

after(cleanupLoadedSource);

const UPDATE_FIXTURES = process.env.PI_MMR_UPDATE_FIXTURES === "1";
const fixtureDir = path.resolve(import.meta.dirname, "fixtures/mmr-tui-tool-groups");

const HOME = "/home/user";
const CWD = "/home/user/proj";

const loadRenderers = () => importSource("extensions/ampi-tui/transcript/tool-renderers.ts");
const loadGroups = () => importSource("extensions/ampi-tui/transcript/activity-groups.ts");

function stripAnsi(text) {
  return text.replace(/\u001b\]8;[^\u0007\u001b]*(?:\u0007|\u001b\\)/g, "").replace(/\u001b\[[0-9;]*m/g, "");
}

const noopTui = { requestRender() {} };

const call = (id, name, args) => ({ type: "toolCall", id, name, arguments: args });
const text = (value) => ({ type: "text", text: value });
const assistant = (content, stopReason = "toolUse") => ({ role: "assistant", content, stopReason });
const output = (value, details) => ({ content: [{ type: "text", text: value }], details });

/** A one-pixel PNG. */
const PNG = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC";

const editDiff =[" 1 import { load } from './load.js';", "-2 const retries = 1;", "+2 const retries = 3;", "+3 const delayMs = 250;"].join("\n");

const READ = call("r1", "read", { path: `${CWD}/src/retry.ts`, offset: 1, limit: 40 });
const BASH = call("b1", "bash", { command: "npm test -- --grep retry" });
const GREP = call("g1", "grep", { pattern: "delayMs", path: "src" });
const EDIT = call("e1", "edit", { path: `${CWD}/src/retry.ts`, edits: [{ oldText: "const retries = 1;", newText: "const retries = 3;\nconst delayMs = 250;" }] });
const LINT = call("b2", "bash", { command: "npm run lint" });
const WRITE = call("w1", "write", { path: `${CWD}/docs/retry.md`, content: "# Retry\n\nThree tries, 250 ms apart.\n" });
const SEARCH = call("s1", "web_search", { query: "exponential backoff jitter" });
const MCP = call("m1", "mcp__docs__search", { query: "retry policy" });

const RESULTS = {
  r1: [output("import { load } from './load.js';")],
  b1: [output("ok 1 - retries three times\nok 2 - waits between tries")],
  g1: [output("src/retry.ts:3:const delayMs = 250;")],
  e1: [output("Successfully replaced 1 block(s) in src/retry.ts.", { diff: editDiff, patch: "" })],
  b2: [output("src/retry.ts:3 unused variable\n\nCommand exited with code 1"), true],
};

/**
 * Play one assistant message through a store and Pi's tool rows in the
 * order Pi's interactive mode uses: extension handlers see each event before
 * the transcript does. Calls listed in `running` start but do not finish.
 */
function playTurn(store, resolver, blocks, { expanded = false, running = [] } = {}) {
  const message = assistant(blocks);
  const rows = new Map();
  store.messageStart(assistant([]));
  for (let i = 1; i <= blocks.length; i++) {
    const partial = assistant(blocks.slice(0, i));
    store.messageUpdate(partial);
    const block = blocks[i - 1];
    const component = new ToolExecutionComponent(block.name, block.id, block.arguments, { showImages: false }, { name: block.name, ...resolver(block.name, () => undefined) }, noopTui, CWD);
    component.setExpanded(expanded);
    rows.set(block.id, component);
  }
  store.messageEnd(message);
  for (const component of rows.values()) component.setArgsComplete();
  for (const block of blocks) {
    store.toolStart(block.id, block.name, block.arguments);
    rows.get(block.id).markExecutionStarted();
  }
  for (const block of blocks) {
    if (running.includes(block.id)) continue;
    finish(store, rows, block.id);
  }
  return rows;
}

function finish(store, rows, id) {
  const [result, isError = false] = RESULTS[id] ?? [output("ok")];
  store.toolEnd(id, result, isError);
  rows.get(id).updateResult({ ...result, isError }, false);
}

/** The transcript lines of the rows, as Pi's chat container stacks them. */
const transcript = (rows, width) => [...rows.values()].flatMap((row) => row.render(width));

async function setup() {
  const { createToolRendererResolver } = await loadRenderers();
  const { ActivityGroupStore } = await loadGroups();
  const store = new ActivityGroupStore();
  return { store, resolver: createToolRendererResolver({ home: HOME, groups: store }) };
}

const SCENARIOS = [
  { name: "finished group", blocks: [READ, BASH, GREP, EDIT] },
  { name: "running group", blocks: [READ, BASH, GREP, EDIT], running: ["b1"] },
  { name: "group with a failed command", blocks: [BASH, LINT] },
  { name: "group of one call", blocks: [GREP] },
  { name: "summary longer than the row", blocks: [READ, BASH, GREP, EDIT, WRITE, SEARCH, MCP] },
];

function assertFixture(filename, actual) {
  const fixturePath = path.join(fixtureDir, filename);
  if (UPDATE_FIXTURES || !existsSync(fixturePath)) {
    mkdirSync(fixtureDir, { recursive: true });
    writeFileSync(fixturePath, actual);
    return;
  }
  assert.equal(actual, readFileSync(fixturePath, "utf8"), `fixture ${filename} drift; rerun with PI_MMR_UPDATE_FIXTURES=1 to refresh`);
}

describe("ampi-tui grouped tool rows", () => {
  for (const width of [80, 140]) {
    it(`renders collapsed and expanded groups at ${width} columns`, async () => {
      mock.timers.enable({ apis: ["setInterval"] });
      try {
        const sections = [];
        for (const scenario of SCENARIOS) {
          for (const expanded of [false, true]) {
            const { store, resolver } = await setup();
            const rows = playTurn(store, resolver, scenario.blocks, { expanded, running: scenario.running });
            const lines = transcript(rows, width);
            for (const line of lines) {
              assert.ok(stripAnsi(line).length <= width, `${scenario.name}: line wider than ${width}: ${JSON.stringify(stripAnsi(line))}`);
            }
            sections.push(`=== ${scenario.name} · ${expanded ? "expanded" : "collapsed"} ===`, ...lines.map(stripAnsi));
            for (const id of scenario.running ?? []) finish(store, rows, id);
          }
        }
        assertFixture(`groups-${width}.txt`, `${sections.join("\n")}\n`);
      } finally {
        mock.timers.reset();
      }
    });
  }

  it("draws the summary on the first row and nothing on the others while collapsed", async () => {
    const { store, resolver } = await setup();
    const rows = playTurn(store, resolver, [READ, BASH, GREP, EDIT]);
    const [first, ...others] = [...rows.values()];
    assert.deepEqual(first.render(140).map(stripAnsi), ["", " ✓ Read 1 file, ran 1 command, ran 1 search, edited 1 file (+2 -1) ▸"]);
    for (const row of others) assert.deepEqual(row.render(140), [], "a hidden row leaves no blank line");
  });

  it("keeps a green check on a group with a failed command and shows the failure on the expanded row", async () => {
    const { store, resolver } = await setup();
    const rows = playTurn(store, resolver, [BASH, LINT]);
    const [first, second] = [...rows.values()];
    assert.match(first.render(80)[1], /\u001b\[[0-9;]*m✓/);
    assert.equal(stripAnsi(first.render(80)[1]), " ✓ Ran 2 commands ▸");
    for (const row of rows.values()) row.setExpanded(true);
    assert.equal(stripAnsi(second.render(80)[1]), "   $ npm run lint (exit code: 1)");
  });

  it("styles the phrase in the title colour with muted separators and arrow", async () => {
    const { createToolRendererResolver } = await loadRenderers();
    const { ActivityGroupStore } = await loadGroups();
    const store = new ActivityGroupStore();
    const resolver = createToolRendererResolver({ home: HOME, groups: store });
    playTurn(store, resolver, [READ, EDIT]);
    const theme = { fg: (color, value) => `<${color}>${value}</${color}>`, bold: (v) => v, italic: (v) => v, underline: (v) => v, strikethrough: (v) => v };
    const renderers = resolver("read", () => undefined);
    const context = { args: READ.arguments, toolCallId: "r1", invalidate() {}, state: {}, cwd: CWD, executionStarted: false, argsComplete: true, isPartial: false, expanded: false, showImages: false, isError: false, outputPad: 1 };
    assert.equal(
      renderers.renderCall(READ.arguments, theme, context).render(400)[0],
      " <success>✓</success> <toolTitle>Read 1 file</toolTitle><muted>, </muted><toolTitle>edited 1 file</toolTitle><muted> (</muted><toolTitle>+2 -1</toolTitle><muted>)</muted> <muted>▸</muted>",
    );
  });

  it("expands the whole group when only its first row is expanded, as a click on it does", async () => {
    const { store, resolver } = await setup();
    const rows = playTurn(store, resolver, [READ, BASH]);
    const [first, second] = [...rows.values()];
    first.setExpanded(true);
    assert.equal(stripAnsi(first.render(80)[1]), " ✓ Read 1 file, ran 1 command ▾");
    assert.equal(stripAnsi(second.render(80)[1]), "   $ npm test -- --grep retry");
    first.setExpanded(false);
    assert.deepEqual(second.render(80), []);
  });

  it("animates the summary while any call runs and stops once the last one finished", async () => {
    mock.timers.enable({ apis: ["setInterval"] });
    try {
      const { store, resolver } = await setup();
      const rows = playTurn(store, resolver, [READ, BASH, GREP], { running: ["r1", "g1"] });
      const first = rows.get("r1");
      assert.equal(stripAnsi(first.render(80)[1]), " ⠋ Reading 1 file, ran 1 command, running 1 search ▸");
      finish(store, rows, "r1");
      mock.timers.tick(80);
      assert.equal(stripAnsi(first.render(80)[1]), " ⠙ Read 1 file, ran 1 command, running 1 search ▸", "the first call finished, the group still runs");
      finish(store, rows, "g1");
      assert.equal(stripAnsi(first.render(80)[1]), " ✓ Read 1 file, ran 1 command, ran 1 search ▸");
      mock.timers.tick(800);
      assert.equal(stripAnsi(first.render(80)[1]), " ✓ Read 1 file, ran 1 command, ran 1 search ▸");
    } finally {
      mock.timers.reset();
    }
  });

  it("keeps one row per call in an HTML export, which draws each call once with its execution started", async () => {
    const { store, resolver } = await setup();
    playTurn(store, resolver, [READ, BASH]);
    const renderers = resolver("bash", () => undefined);
    const context = { args: BASH.arguments, toolCallId: "b1", invalidate() {}, state: {}, cwd: CWD, executionStarted: true, argsComplete: true, isPartial: false, expanded: false, showImages: false, isError: false, outputPad: 1 };
    const plain = { fg: (_color, value) => value, bold: (v) => v, italic: (v) => v, underline: (v) => v, strikethrough: (v) => v };
    assert.deepEqual(renderers.renderCall(BASH.arguments, plain, context).render(80), []);
    const result = renderers.renderResult(RESULTS.b1[0], { expanded: false, isPartial: false }, plain, context);
    assert.deepEqual(result.render(80), [" ✓ Ran npm test -- --grep retry"]);
  });

  it("draws a subagent call on its own row between two groups", async () => {
    const { store, resolver } = await setup();
    const oracle = call("o1", "oracle", { task: "Review the retry plan" });
    const rows = playTurn(store, resolver, [READ, oracle, GREP]);
    assert.deepEqual(transcript(rows, 80).map(stripAnsi), [
      "",
      " ✓ Read 1 file ▸",
      "",
      " ✓ Consulted oracle · Review the retry plan",
      "",
      " ✓ Ran 1 search ▸",
    ]);
  });
});

describe("ampi-tui grouped tool rows through the extension", () => {
  /** Pi's tool row for a call, drawn with the resolver the extension registered. */
  function piRow(resolver, block) {
    return new ToolExecutionComponent(block.name, block.id, block.arguments, { showImages: true }, { name: block.name, ...resolver(block.name, () => undefined) }, noopTui, CWD);
  }

  /** An interactive session's context whose session holds `messages`, read when a handler asks. */
  function tuiContext(messages, mode = "tui") {
    const entries = () => messages.map((message, i) => ({ type: "message", id: `e${i}`, message }));
    return { mode, sessionManager: { buildContextEntries: entries } };
  }

  /** Play assistant messages through the extension's handlers and Pi's rows, persisting them as Pi does. */
  function livePlayer(handlers, resolver, ctx, session) {
    const rows = [];
    const play = (blocks, results = RESULTS) => {
      const message = assistant(blocks);
      handlers.get("message_start")({ type: "message_start", message: assistant([]) }, ctx);
      handlers.get("message_update")({ type: "message_update", message }, ctx);
      for (const block of blocks.filter((b) => b.type === "toolCall")) rows.push(piRow(resolver, block));
      handlers.get("message_end")({ type: "message_end", message }, ctx);
      session.push(message);
      for (const block of blocks.filter((b) => b.type === "toolCall")) {
        const row = rows.find((r) => r.toolCallId === block.id);
        handlers.get("tool_execution_start")({ type: "tool_execution_start", toolCallId: block.id, toolName: block.name, args: block.arguments }, ctx);
        row.markExecutionStarted();
        const [result, isError = false] = results[block.id];
        handlers.get("tool_execution_end")({ type: "tool_execution_end", toolCallId: block.id, toolName: block.name, result, isError }, ctx);
        row.updateResult({ ...result, isError }, false);
        session.push({ role: "toolResult", toolCallId: block.id, content: result.content, isError });
      }
    };
    return { rows, play };
  }

  it("groups a resumed session's calls and leaves the later rows zero-height", async () => {
    const { installToolRenderers } = await loadRenderers();
    const { pi, handlers, toolRenderers } = createMockPi();
    installToolRenderers(pi, { home: HOME });
    const blocks = [READ, BASH, GREP];
    const messages = [
      { role: "user", content: [text("Check the retry logic.")] },
      assistant(blocks),
      ...blocks.map((block) => ({ role: "toolResult", toolCallId: block.id, content: RESULTS[block.id][0].content, isError: false })),
    ];
    handlers.get("session_start")({ type: "session_start", reason: "resume" }, tuiContext(messages));
    // Pi replays the session after session_start: a row per call, then its result.
    const rows = blocks.map((block) => piRow(toolRenderers[0], block));
    for (const [i, row] of rows.entries()) row.updateResult(messages[2 + i]);
    assert.deepEqual(rows.map((row) => row.render(80).map(stripAnsi)), [["", " ✓ Read 1 file, ran 1 command, ran 1 search ▸"], [], []]);
  });

  it("follows a live turn from Pi's events and splits the run at assistant text", async () => {
    const { installToolRenderers } = await loadRenderers();
    const { pi, handlers, toolRenderers } = createMockPi();
    installToolRenderers(pi, { home: HOME });
    const session = [];
    const ctx = tuiContext(session);
    handlers.get("session_start")({ type: "session_start", reason: "startup" }, ctx);
    const { rows, play } = livePlayer(handlers, toolRenderers[0], ctx, session);
    play([READ, BASH]);
    play([GREP]);
    play([text("Now the fix."), EDIT]);
    // A shown custom message Pi adds after a turn without an extension event.
    session.push({ role: "custom", customType: "note", display: true, content: "Deploy is frozen." });
    play([LINT]);
    assert.deepEqual(rows.map((row) => row.render(80).map(stripAnsi)), [
      ["", " ✓ Read 1 file, ran 1 command, ran 1 search ▸"],
      [],
      [],
      ["", " ✓ Edited 1 file (+2 -1) ▸"],
      ["", " ✓ Ran 1 command ▸"],
    ]);
  });

  it("gives a call whose image shows its own row above the image", async () => {
    const { installToolRenderers } = await loadRenderers();
    const original = getCapabilities();
    setCapabilities({ ...original, images: "kitty" });
    try {
      const { pi, handlers, toolRenderers } = createMockPi();
      installToolRenderers(pi, { home: HOME });
      const session = [];
      const ctx = tuiContext(session);
      handlers.get("session_start")({ type: "session_start", reason: "startup" }, ctx);
      const { rows, play } = livePlayer(handlers, toolRenderers[0], ctx, session);
      const shot = call("r2", "read", { path: `${CWD}/shot.png` });
      const image = { content: [text("Read image file [image/png]"), { type: "image", data: PNG, mimeType: "image/png" }] };
      play([BASH, shot, GREP], { ...RESULTS, r2: [image] });
      const [bash, read, grep] = rows.map((row) => row.render(80).map(stripAnsi));
      assert.deepEqual(bash, ["", " ✓ Ran 1 command ▸"]);
      assert.deepEqual(read.slice(0, 3), ["", " ✓ Read shot.png", ""], "the row's title, then Pi's spacer and the image");
      assert.ok(read.length > 3, "the image follows its row");
      assert.deepEqual(grep, ["", " ✓ Ran 1 search ▸"]);
    } finally {
      setCapabilities(original);
    }
  });

  it("leaves sessions without a transcript alone", async () => {
    const { installToolRenderers } = await loadRenderers();
    const { pi, handlers, toolRenderers } = createMockPi();
    installToolRenderers(pi, { home: HOME });
    let reads = 0;
    const buildContextEntries = () => {
      reads++;
      return [];
    };
    const ctx = { mode: "print", sessionManager: { buildContextEntries } };
    handlers.get("session_start")({ type: "session_start", reason: "startup" }, ctx);
    const { rows, play } = livePlayer(handlers, toolRenderers[0], ctx, []);
    play([READ, BASH]);
    assert.equal(reads, 0, "the session is never read");
    assert.equal(stripAnsi(rows[1].render(80)[1]), " ✓ Ran npm test -- --grep retry", "each call keeps its own row");
  });
});
